const Trade* find_trade(const std::string& code) noexcept {
  for(const auto& row:trades())if(row.capability==code)return &row;
  return nullptr;}
const ServiceRole* find_service_role(const std::string& code) noexcept {
  for(const auto& row:service_roles())if(row.staff_role==code)return &row;
  return nullptr;}
void validate_against_industry01(){
  industry01::validate_against_original_inventory();
  std::set<std::string> sites,staff;
  unsigned native=0;
  for(const auto& t:trades()){
    if(!sites.insert(t.capability).second || !t.minimum_workers || !t.power_required)
      throw std::invalid_argument("WO2 invalid profession capacity");
    if(t.native_execution){
      ++native;
      const bool cut=t.capability=="cut",shape=t.capability=="shape";
      if((!cut&&!shape)||t.level!="native_baseline"||t.minimum_workers!=1||t.training_units!=0||
         t.native_binding!=(cut?"native_cut_aluminum_panel":"native_shape_aluminum_frame")||
         !industry01::is_native_workshop_recipe(t.native_binding))
         throw std::invalid_argument("WO2 unauthorized native work binding");
    }else if(!t.native_binding.empty()||t.level=="native_baseline")
      throw std::invalid_argument("WO2 fake qualified worker");
  }
  if(native!=2)throw std::invalid_argument("WO2 unexpected native executor count");
  for(const auto& r:industry01::recipes()){
    if(!find_trade(r.site_capability))throw std::invalid_argument("WO2 recipe has no profession");}
  for(const auto& r:industry01::recovery_recipes()){
    if(!find_trade(r.recipe.site_capability))throw std::invalid_argument("WO2 recovery has no profession");}
  for(const auto& r:service_roles()){
    if(!staff.insert(r.staff_role).second)throw std::invalid_argument("WO2 duplicate service worker");}
  for(const auto& svc:industry01::services()){
    for(const auto& role:svc.staff)
      if(!find_service_role(role))throw std::invalid_argument("WO2 service staff missing");
  }
}
